import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

let initState = {
  name: "",
  email: "",
  password: "",
  city: "",
  country: "",
};

function SignUp() {
  const [name, setName] = useState(initState.name);
  const [email, setEmail] = useState(initState.email);
  const [password, setPassword] = useState(initState.password);
  const [city, setCity] = useState(initState.city);
  const [country, setCountry] = useState(initState.country);
  const [submitted, setSubmitted] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    if (submitted) {
      navigate("/login");
    }
  }, [submitted, navigate]);

  function handleSubmit(e) {
    e.preventDefault();
    if (!name || !email || !password || !city || !country) {
      alert("Input Fields Cannot Be Empty!");
      return;
    }

    axios
      .post(`https://rctmockapi.onrender.com/user`, {
        name,
        email,
        password,
        city,
        country,
      })
      .then((res) => {
        setSubmitted(true);
      })
      .catch((err) => {
        console.log(err);
      });
  }

  return (
    <div className="min-h-[85vh] flex items-center justify-center px-4 py-12">
      <div className="bg-[#304b62] w-full max-w-[480px] rounded-2xl shadow-xl p-8 md:p-10">
        <h1 className="text-2xl md:text-3xl font-extrabold text-white mb-6">
          Register Here:
        </h1>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-white font-medium text-sm md:text-base mb-1.5">
              Name <span className="text-red-300">*</span>
            </label>
            <input
              type="text"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full bg-white text-slate-800 text-base px-4 py-2 rounded-md border border-transparent focus:outline-none focus:ring-2 focus:ring-[#d49539]"
              placeholder="Your Full Name"
            />
          </div>

          <div>
            <label className="block text-white font-medium text-sm md:text-base mb-1.5">
              Email address <span className="text-red-300">*</span>
            </label>
            <input
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-white text-slate-800 text-base px-4 py-2 rounded-md border border-transparent focus:outline-none focus:ring-2 focus:ring-[#d49539]"
              placeholder="name@example.com"
            />
          </div>

          <div>
            <label className="block text-white font-medium text-sm md:text-base mb-1.5">
              Password <span className="text-red-300">*</span>
            </label>
            <input
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-white text-slate-800 text-base px-4 py-2 rounded-md border border-transparent focus:outline-none focus:ring-2 focus:ring-[#d49539]"
              placeholder="••••••••"
            />
          </div>

          <div>
            <label className="block text-white font-medium text-sm md:text-base mb-1.5">
              City <span className="text-red-300">*</span>
            </label>
            <input
              type="text"
              required
              value={city}
              onChange={(e) => setCity(e.target.value)}
              className="w-full bg-white text-slate-800 text-base px-4 py-2 rounded-md border border-transparent focus:outline-none focus:ring-2 focus:ring-[#d49539]"
              placeholder="City"
            />
          </div>

          <div>
            <label className="block text-white font-medium text-sm md:text-base mb-1.5">
              Country <span className="text-red-300">*</span>
            </label>
            <input
              type="text"
              required
              value={country}
              onChange={(e) => setCountry(e.target.value)}
              className="w-full bg-white text-slate-800 text-base px-4 py-2 rounded-md border border-transparent focus:outline-none focus:ring-2 focus:ring-[#d49539]"
              placeholder="Country"
            />
          </div>

          <div className="pt-4">
            <button
              type="submit"
              className="w-full bg-[#d49539] hover:bg-[#c0832d] text-white font-bold py-3 px-6 rounded-md transition-colors shadow-md text-base"
            >
              Submit
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default SignUp;
